//! Phase C — AEAD error paths (`ERRORS.md` rows for the `crypto_aead_*` group).
//!
//! Two kinds of row:
//!
//! * **`return -1` rows** — called directly on both `.so`s; the return value,
//!   the out-parameters (`*mlen_p`) and the output buffer contents (whether the
//!   plaintext got zeroed) must match byte-for-byte.
//! * **`sodium_misuse()` rows** — `sodium_misuse()` runs the installed handler
//!   and then `abort()`s. Each such row is run in a **child process** (once
//!   against the C `.so`, once against the Rust `.so`) with an observing
//!   handler installed, so the abort *and* the side effects written before it
//!   are compared exactly.
//!
//! ### Row coverage (generated by `.phaseA/rowmap_mine.py`)
//!
//! | test | table | rows |
//! |---|---|---|
//! | `decrypt_clen_below_abytes` | ERRORS | G3-005, G3-006, G3-021, G3-022, G3-034, G3-035, G3-043, G3-044, G3-054, G3-055 |
//! | `decrypt_bad_tag_zeroes_plaintext` | ERRORS | G3-007, G3-008, G3-009, G3-023, G3-024, G3-025, G3-036, G3-037, G3-038, G3-045, G3-046, G3-048, G3-056, G3-057, G3-060 |
//! | `decrypt_ad_mismatch` | ERRORS | G3-047 |
//! | `xchacha_wrong_nonce_halves` | ERRORS | G3-058, G3-059 |
//! | `decrypt_detached_bad_mac` | ERRORS | G3-013, G3-014, G3-029, G3-030, G3-039, G3-040, G3-049, G3-050, G3-061, G3-062 |
//! | `aegis_decrypt_oversized_lengths_return_minus_one` | ERRORS | G3-010, G3-011, G3-012, G3-026, G3-027, G3-028 |
//! | `aes256gcm_sets_enosys` | ERRORS | G3-064, G3-065, G3-066, G3-067, G3-068, G3-069, G3-070, G3-071, G3-072 |
//! | `aes256gcm_sets_enosys` | CONFIGS | G3-124, G3-125, G3-126, G3-127 |
//! | `misuse_paths_match` | ERRORS | G3-001, G3-002, G3-003, G3-004, G3-017, G3-018, G3-019, G3-020, G3-033, G3-042, G3-053, G3-078 |
//! | `misuse_without_handler_aborts_identically` | ERRORS | G3-001 |
//! | `misuse_without_handler_aborts_identically` | CONFIGS | G3-129 |
//! | `documented_unreachable_error_rows` | ERRORS | G3-015, G3-016, G3-031, G3-032, G3-041, G3-051, G3-052, G3-063, G3-074, G3-076, G3-077, G3-079, G3-080 |
//! | `documented_unreachable_error_rows` | CONFIGS | G3-031, G3-058, G3-108 |

mod common;
use common::*;

type Enc = unsafe extern "C" fn(
    *mut u8, *mut u64, *const u8, u64, *const u8, u64, *const u8, *const u8, *const u8,
) -> i32;
type Dec = unsafe extern "C" fn(
    *mut u8, *mut u64, *mut u8, *const u8, u64, *const u8, u64, *const u8, *const u8,
) -> i32;
type EncDet = unsafe extern "C" fn(
    *mut u8, *mut u8, *mut u64, *const u8, u64, *const u8, u64, *const u8, *const u8, *const u8,
) -> i32;
type DecDet = unsafe extern "C" fn(
    *mut u8, *mut u8, *const u8, u64, *const u8, *const u8, u64, *const u8, *const u8,
) -> i32;

const AEADS: &[&str] = &[
    "crypto_aead_aegis128l",
    "crypto_aead_aegis256",
    "crypto_aead_chacha20poly1305",
    "crypto_aead_chacha20poly1305_ietf",
    "crypto_aead_xchacha20poly1305_ietf",
];

fn g(p: &str, s: &str) -> usize {
    unsafe { sym::<unsafe extern "C" fn() -> usize>(c_lib(), &format!("{p}_{s}"))() }
}
fn gmax(p: &str) -> u64 {
    unsafe { sym::<unsafe extern "C" fn() -> u64>(c_lib(), &format!("{p}_messagebytes_max"))() }
}

// ===========================================================================
// `return -1` rows
// ===========================================================================

/// ERRORS rows: `_decrypt` with `clen < ABYTES` (0 and ABYTES-1) —
/// returns -1, `*mlen_p` set to 0, output buffer untouched.
#[test]
fn decrypt_clen_below_abytes() {
    setup();
    let mut rng = Rng::new(0x9000);
    for &p in AEADS {
        let ab = g(p, "abytes");
        let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
        for clen in 0..=ab {
            if clen == ab {
                continue; // ab itself is valid (mlen = 0)
            }
            let k = rng.bytes(g(p, "keybytes"));
            let npub = rng.bytes(g(p, "npubbytes"));
            let c = rng.bytes(ab.max(1));
            for mlen_p_null in [false, true] {
                let mut m1 = canary(64);
                let mut m2 = canary(64);
                let mut o1 = 0xDEAD_BEEF_u64;
                let mut o2 = 0xDEAD_BEEF_u64;
                let (p1, p2) = if mlen_p_null {
                    (std::ptr::null_mut(), std::ptr::null_mut())
                } else {
                    (&raw mut o1, &raw mut o2)
                };
                let (ra, rb) = unsafe {
                    (
                        cd(m1.as_mut_ptr(), p1, std::ptr::null_mut(), c.as_ptr(),
                           clen as u64, std::ptr::null(), 0, npub.as_ptr(), k.as_ptr()),
                        rd(m2.as_mut_ptr(), p2, std::ptr::null_mut(), c.as_ptr(),
                           clen as u64, std::ptr::null(), 0, npub.as_ptr(), k.as_ptr()),
                    )
                };
                eq_i32(&format!("{p}_decrypt(clen={clen}) rc"), ra, rb);
                assert_eq!(ra, -1, "{p}_decrypt(clen={clen}) must reject");
                eq_usize(&format!("{p}_decrypt(clen={clen}) *mlen_p"), o1 as usize, o2 as usize);
                if !mlen_p_null {
                    assert_eq!(o1, 0, "{p}_decrypt short clen must set *mlen_p = 0");
                }
                eq_bytes(&format!("{p}_decrypt(clen={clen}) m untouched"), &m1, &m2);
                assert_eq!(m1, canary(64), "{p}_decrypt short clen wrote to m");
            }
        }
    }
}

/// ERRORS rows: `_decrypt` with a wrong tag — for `mlen == 0` (`memset` is a
/// no-op) and for `mlen > 0` (the plaintext region must be zeroed).
#[test]
fn decrypt_bad_tag_zeroes_plaintext() {
    setup();
    let mut rng = Rng::new(0x9001);
    for &p in AEADS {
        let ab = g(p, "abytes");
        let (ce, _) = pair::<Enc>(&format!("{p}_encrypt"));
        let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
        for &mlen in &[0usize, 1, 16, 32, 100] {
            for &adlen in &[0usize, 16] {
                let k = rng.bytes(g(p, "keybytes"));
                let npub = rng.bytes(g(p, "npubbytes"));
                let m = rng.bytes(mlen);
                let ad = rng.bytes(adlen);
                let mut good = canary(mlen + ab);
                unsafe {
                    ce(good.as_mut_ptr(), std::ptr::null_mut(), m.as_ptr(), mlen as u64,
                       ad.as_ptr(), adlen as u64, std::ptr::null(), npub.as_ptr(), k.as_ptr());
                }
                // Corrupt in three distinct places: tag first byte, tag last
                // byte, and (when mlen > 0) a ciphertext byte.
                let mut variants: Vec<(String, Vec<u8>)> = Vec::new();
                let mut v = good.clone();
                v[mlen] ^= 0x01;
                variants.push(("tag[0]".into(), v));
                let mut v = good.clone();
                let last = v.len() - 1;
                v[last] ^= 0x80;
                variants.push(("tag[last]".into(), v));
                if mlen > 0 {
                    let mut v = good.clone();
                    v[0] ^= 0x01;
                    variants.push(("c[0]".into(), v));
                }
                for (what, bad) in variants {
                    for m_null in [false, true] {
                        let mut m1 = canary(mlen.max(1));
                        let mut m2 = canary(mlen.max(1));
                        let mut o1 = 0xDEAD_u64;
                        let mut o2 = 0xDEAD_u64;
                        let (mp1, mp2) = if m_null {
                            (std::ptr::null_mut(), std::ptr::null_mut())
                        } else {
                            (m1.as_mut_ptr(), m2.as_mut_ptr())
                        };
                        let (ra, rb) = unsafe {
                            (
                                cd(mp1, &mut o1, std::ptr::null_mut(), bad.as_ptr(),
                                   bad.len() as u64, ad.as_ptr(), adlen as u64,
                                   npub.as_ptr(), k.as_ptr()),
                                rd(mp2, &mut o2, std::ptr::null_mut(), bad.as_ptr(),
                                   bad.len() as u64, ad.as_ptr(), adlen as u64,
                                   npub.as_ptr(), k.as_ptr()),
                            )
                        };
                        eq_i32(&format!("{p}_decrypt bad {what} m_null={m_null} rc"), ra, rb);
                        assert_eq!(ra, -1);
                        eq_usize(
                            &format!("{p}_decrypt bad {what} *mlen_p"),
                            o1 as usize, o2 as usize,
                        );
                        assert_eq!(o1, 0);
                        eq_bytes(
                            &format!("{p}_decrypt bad {what} m_null={m_null} buffer"),
                            &m1, &m2,
                        );
                        if !m_null && mlen > 0 {
                            assert_eq!(
                                m1, vec![0u8; mlen],
                                "{p}_decrypt must zero the plaintext on tag failure"
                            );
                        }
                        if m_null {
                            assert_eq!(
                                m1, canary(mlen.max(1)),
                                "{p}_decrypt m=NULL must not write anything"
                            );
                        }
                    }
                }
            }
        }
    }
}

/// ERRORS row: `_decrypt` with a *correct* tag but mismatched AD.
#[test]
fn decrypt_ad_mismatch() {
    setup();
    let mut rng = Rng::new(0x9002);
    for &p in AEADS {
        let ab = g(p, "abytes");
        let (ce, _) = pair::<Enc>(&format!("{p}_encrypt"));
        let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
        let mlen = 100usize;
        for &(enc_ad, dec_ad) in &[(16usize, 0usize), (0, 16), (16, 17), (17, 16), (100, 99)] {
            let k = rng.bytes(g(p, "keybytes"));
            let npub = rng.bytes(g(p, "npubbytes"));
            let m = rng.bytes(mlen);
            let ad = rng.bytes(enc_ad.max(dec_ad));
            let mut c = canary(mlen + ab);
            unsafe {
                ce(c.as_mut_ptr(), std::ptr::null_mut(), m.as_ptr(), mlen as u64,
                   ad.as_ptr(), enc_ad as u64, std::ptr::null(), npub.as_ptr(), k.as_ptr());
            }
            let mut m1 = canary(mlen);
            let mut m2 = canary(mlen);
            let mut o1 = 0xDEADu64;
            let mut o2 = 0xDEADu64;
            let (ra, rb) = unsafe {
                (
                    cd(m1.as_mut_ptr(), &mut o1, std::ptr::null_mut(), c.as_ptr(),
                       (mlen + ab) as u64, ad.as_ptr(), dec_ad as u64, npub.as_ptr(), k.as_ptr()),
                    rd(m2.as_mut_ptr(), &mut o2, std::ptr::null_mut(), c.as_ptr(),
                       (mlen + ab) as u64, ad.as_ptr(), dec_ad as u64, npub.as_ptr(), k.as_ptr()),
                )
            };
            eq_i32(&format!("{p} ad mismatch {enc_ad}->{dec_ad} rc"), ra, rb);
            assert_eq!(ra, -1);
            eq_usize(&format!("{p} ad mismatch *mlen_p"), o1 as usize, o2 as usize);
            eq_bytes(&format!("{p} ad mismatch m"), &m1, &m2);
        }
    }
}

/// ERRORS rows: xchacha20poly1305 with a nonce wrong in the first half (the
/// hchacha20 subkey) vs the second half (`npub2[4..12]`) — two distinct
/// dependencies, both must reject identically.
#[test]
fn xchacha_wrong_nonce_halves() {
    setup();
    let mut rng = Rng::new(0x9003);
    let p = "crypto_aead_xchacha20poly1305_ietf";
    let (ce, _) = pair::<Enc>(&format!("{p}_encrypt"));
    let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
    let mlen = 100usize;
    for byte_idx in [0usize, 5, 15, 16, 20, 23] {
        let k = rng.bytes(32);
        let npub = rng.bytes(24);
        let m = rng.bytes(mlen);
        let mut c = canary(mlen + 16);
        unsafe {
            ce(c.as_mut_ptr(), std::ptr::null_mut(), m.as_ptr(), mlen as u64,
               std::ptr::null(), 0, std::ptr::null(), npub.as_ptr(), k.as_ptr());
        }
        let mut bad = npub.clone();
        bad[byte_idx] ^= 0xff;
        let mut m1 = canary(mlen);
        let mut m2 = canary(mlen);
        let mut o1 = 0xDEADu64;
        let mut o2 = 0xDEADu64;
        let (ra, rb) = unsafe {
            (
                cd(m1.as_mut_ptr(), &mut o1, std::ptr::null_mut(), c.as_ptr(),
                   (mlen + 16) as u64, std::ptr::null(), 0, bad.as_ptr(), k.as_ptr()),
                rd(m2.as_mut_ptr(), &mut o2, std::ptr::null_mut(), c.as_ptr(),
                   (mlen + 16) as u64, std::ptr::null(), 0, bad.as_ptr(), k.as_ptr()),
            )
        };
        eq_i32(&format!("xchacha wrong npub[{byte_idx}] rc"), ra, rb);
        assert_eq!(ra, -1);
        eq_usize("xchacha wrong npub *mlen_p", o1 as usize, o2 as usize);
        eq_bytes(&format!("xchacha wrong npub[{byte_idx}] m"), &m1, &m2);
        assert_eq!(m1, vec![0u8; mlen]);
    }
}

/// ERRORS rows: `_decrypt_detached` with a wrong MAC (with and without `m`).
#[test]
fn decrypt_detached_bad_mac() {
    setup();
    let mut rng = Rng::new(0x9004);
    for &p in AEADS {
        let ab = g(p, "abytes");
        let (ced, _) = pair::<EncDet>(&format!("{p}_encrypt_detached"));
        let (cdd, rdd) = pair::<DecDet>(&format!("{p}_decrypt_detached"));
        for &clen in &[0usize, 1, 5, 16, 32, 100] {
            let k = rng.bytes(g(p, "keybytes"));
            let npub = rng.bytes(g(p, "npubbytes"));
            let m = rng.bytes(clen);
            let mut c = canary(clen.max(1));
            let mut tag = canary(ab);
            unsafe {
                ced(c.as_mut_ptr(), tag.as_mut_ptr(), std::ptr::null_mut(),
                    m.as_ptr(), clen as u64, std::ptr::null(), 0,
                    std::ptr::null(), npub.as_ptr(), k.as_ptr());
            }
            // three distinct wrong MACs, incl. the all-zero and all-ff ones the
            // table calls out explicitly
            let mut macs: Vec<(String, Vec<u8>)> = vec![
                ("zero".into(), vec![0u8; ab]),
                ("ff".into(), vec![0xffu8; ab]),
            ];
            let mut flip = tag.clone();
            flip[0] ^= 1;
            macs.push(("flip0".into(), flip));
            let mut flip = tag.clone();
            flip[ab - 1] ^= 0x80;
            macs.push(("flipN".into(), flip));
            for (what, mac) in macs {
                if mac == tag {
                    continue;
                }
                for m_null in [false, true] {
                    let mut m1 = canary(clen.max(1));
                    let mut m2 = canary(clen.max(1));
                    let (mp1, mp2) = if m_null {
                        (std::ptr::null_mut(), std::ptr::null_mut())
                    } else {
                        (m1.as_mut_ptr(), m2.as_mut_ptr())
                    };
                    let (ra, rb) = unsafe {
                        (
                            cdd(mp1, std::ptr::null_mut(), c.as_ptr(), clen as u64,
                                mac.as_ptr(), std::ptr::null(), 0, npub.as_ptr(), k.as_ptr()),
                            rdd(mp2, std::ptr::null_mut(), c.as_ptr(), clen as u64,
                                mac.as_ptr(), std::ptr::null(), 0, npub.as_ptr(), k.as_ptr()),
                        )
                    };
                    eq_i32(
                        &format!("{p}_decrypt_detached mac={what} clen={clen} m_null={m_null} rc"),
                        ra, rb,
                    );
                    assert_eq!(ra, -1);
                    eq_bytes(
                        &format!("{p}_decrypt_detached mac={what} clen={clen} m_null={m_null}"),
                        &m1, &m2,
                    );
                    if m_null {
                        assert_eq!(m1, canary(clen.max(1)), "{p} m=NULL must not write");
                    } else if clen > 0 {
                        assert_eq!(m1, vec![0u8; clen], "{p} must zero m on MAC failure");
                    }
                }
            }
        }
    }
}

/// ERRORS rows: AEGIS `_decrypt_detached` with `clen`/`adlen` above
/// `MESSAGEBYTES_MAX` returns `-1` *immediately* (asymmetric with the encrypt
/// side, which aborts). The guard precedes every dereference, so no buffer is
/// needed. Also the combined `_decrypt` with `clen = MAX + ABYTES + 1`.
#[test]
fn aegis_decrypt_oversized_lengths_return_minus_one() {
    setup();
    for &p in &["crypto_aead_aegis128l", "crypto_aead_aegis256"] {
        let ab = g(p, "abytes") as u64;
        let max = gmax(p);
        let (cdd, rdd) = pair::<DecDet>(&format!("{p}_decrypt_detached"));
        let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
        let k = [7u8; 32];
        let npub = [9u8; 32];
        let mac = [0u8; 32];
        let cbuf = [0u8; 64];

        for &(clen, adlen, what) in &[
            (max + 1, 0u64, "clen = MAX+1"),
            (u64::MAX, 0, "clen = u64::MAX"),
            (0, max + 1, "adlen = MAX+1"),
            (0, u64::MAX, "adlen = u64::MAX"),
            (max + 1, max + 1, "both = MAX+1"),
        ] {
            let mut m1 = canary(64);
            let mut m2 = canary(64);
            let (ra, rb) = unsafe {
                (
                    cdd(m1.as_mut_ptr(), std::ptr::null_mut(), cbuf.as_ptr(), clen,
                        mac.as_ptr(), std::ptr::null(), adlen, npub.as_ptr(), k.as_ptr()),
                    rdd(m2.as_mut_ptr(), std::ptr::null_mut(), cbuf.as_ptr(), clen,
                        mac.as_ptr(), std::ptr::null(), adlen, npub.as_ptr(), k.as_ptr()),
                )
            };
            eq_i32(&format!("{p}_decrypt_detached {what} rc"), ra, rb);
            assert_eq!(ra, -1, "{p}_decrypt_detached {what} must return -1");
            eq_bytes(&format!("{p}_decrypt_detached {what} m"), &m1, &m2);
            assert_eq!(m1, canary(64));
        }

        // combined _decrypt: clen - ABYTES > MESSAGEBYTES_MAX -> inner guard
        for &clen in &[max + ab + 1, u64::MAX] {
            let mut m1 = canary(64);
            let mut m2 = canary(64);
            let mut o1 = 0xDEADu64;
            let mut o2 = 0xDEADu64;
            let (ra, rb) = unsafe {
                (
                    cd(m1.as_mut_ptr(), &mut o1, std::ptr::null_mut(), cbuf.as_ptr(),
                       clen, std::ptr::null(), 0, npub.as_ptr(), k.as_ptr()),
                    rd(m2.as_mut_ptr(), &mut o2, std::ptr::null_mut(), cbuf.as_ptr(),
                       clen, std::ptr::null(), 0, npub.as_ptr(), k.as_ptr()),
                )
            };
            eq_i32(&format!("{p}_decrypt(clen={clen}) rc"), ra, rb);
            assert_eq!(ra, -1);
            eq_usize(&format!("{p}_decrypt(clen={clen}) *mlen_p"), o1 as usize, o2 as usize);
            assert_eq!(o1, 0);
            eq_bytes(&format!("{p}_decrypt(clen={clen}) m"), &m1, &m2);
        }
    }
}

/// ERRORS rows: all nine operational `crypto_aead_aes256gcm_*` entry points
/// set `errno = ENOSYS` and return `-1` in this build.
#[test]
fn aes256gcm_sets_enosys() {
    setup();
    const ENOSYS: i32 = 38;
    let mut rng = Rng::new(0x9005);
    let k = rng.bytes(32);
    let npub = rng.bytes(12);
    let m = rng.bytes(64);
    let ad = rng.bytes(16);
    let mac = rng.bytes(16);
    let mut out = canary(128);
    let mut len = 0u64;
    let mut st = State::new(512);

    let clear_errno = || {
        // reset errno via a syscall that is known to succeed
        let _ = std::fs::metadata("/");
        let _ = std::io::Error::from_raw_os_error(0);
    };
    let errno = || std::io::Error::last_os_error().raw_os_error().unwrap_or(0);

    macro_rules! check {
        ($name:literal, $ty:ty, $call:expr) => {{
            let (c, r) = pair::<$ty>($name);
            for which in [c, r] {
                clear_errno();
                let f = which;
                let rc = unsafe { $call(f) };
                assert_eq!(rc, -1, concat!($name, " must return -1"));
                assert_eq!(errno(), ENOSYS, concat!($name, " must set errno = ENOSYS"));
            }
        }};
    }

    check!("crypto_aead_aes256gcm_encrypt", Enc, |f: Enc| f(
        out.as_mut_ptr(), &mut len, m.as_ptr(), 64, ad.as_ptr(), 16,
        std::ptr::null(), npub.as_ptr(), k.as_ptr()));
    check!("crypto_aead_aes256gcm_decrypt", Dec, |f: Dec| f(
        out.as_mut_ptr(), &mut len, std::ptr::null_mut(), m.as_ptr(), 64,
        ad.as_ptr(), 16, npub.as_ptr(), k.as_ptr()));
    check!("crypto_aead_aes256gcm_encrypt_detached", EncDet, |f: EncDet| f(
        out.as_mut_ptr(), out.as_mut_ptr(), &mut len, m.as_ptr(), 64,
        ad.as_ptr(), 16, std::ptr::null(), npub.as_ptr(), k.as_ptr()));
    check!("crypto_aead_aes256gcm_decrypt_detached", DecDet, |f: DecDet| f(
        out.as_mut_ptr(), std::ptr::null_mut(), m.as_ptr(), 64, mac.as_ptr(),
        ad.as_ptr(), 16, npub.as_ptr(), k.as_ptr()));
    check!(
        "crypto_aead_aes256gcm_beforenm",
        unsafe extern "C" fn(*mut u8, *const u8) -> i32,
        |f: unsafe extern "C" fn(*mut u8, *const u8) -> i32| f(st.as_mut_ptr(), k.as_ptr())
    );

    type EncAfter = unsafe extern "C" fn(
        *mut u8, *mut u64, *const u8, u64, *const u8, u64, *const u8, *const u8, *const u8,
    ) -> i32;
    for name in [
        "crypto_aead_aes256gcm_encrypt_afternm",
        "crypto_aead_aes256gcm_decrypt_afternm",
        "crypto_aead_aes256gcm_encrypt_detached_afternm",
        "crypto_aead_aes256gcm_decrypt_detached_afternm",
    ] {
        let (c, r) = pair::<EncAfter>(name);
        for f in [c, r] {
            clear_errno();
            let rc = unsafe {
                f(out.as_mut_ptr(), &mut len, m.as_ptr(), 64, ad.as_ptr(), 16,
                  std::ptr::null(), npub.as_ptr(), st.as_ptr())
            };
            assert_eq!(rc, -1, "{name} must return -1");
            assert_eq!(errno(), ENOSYS, "{name} must set errno = ENOSYS");
        }
    }
}

// ===========================================================================
// `sodium_misuse()` rows — run out of process
// ===========================================================================

/// Every abort-path row, identified by tag.
const MISUSE_CASES: &[&str] = &[
    // aegis128l / aegis256 combined encrypt: mlen > MESSAGEBYTES_MAX
    "aegis128l/encrypt/mlen=max+1",
    "aegis128l/encrypt/mlen=u64max",
    "aegis256/encrypt/mlen=max+1",
    "aegis256/encrypt/mlen=u64max",
    // combined encrypt with oversized adlen (guard lives in _encrypt_detached)
    "aegis128l/encrypt/adlen=max+1",
    "aegis256/encrypt/adlen=max+1",
    // detached encrypt: *maclen_p is written BEFORE the abort
    "aegis128l/encrypt_detached/mlen=max+1",
    "aegis128l/encrypt_detached/adlen=max+1",
    "aegis256/encrypt_detached/mlen=max+1",
    "aegis256/encrypt_detached/adlen=max+1",
    // poly1305 AEADs: combined encrypt guards
    "chacha20poly1305/encrypt/mlen=max+1",
    "chacha20poly1305_ietf/encrypt/mlen=max+1",
    "chacha20poly1305_ietf/encrypt/mlen=u64max",
    "xchacha20poly1305_ietf/encrypt/mlen=max+1",
];

fn prefix_of(tag: &str) -> String {
    format!("crypto_aead_{}", tag.split('/').next().unwrap())
}

/// The child half: performs exactly one misusing call on the selected library.
#[test]
fn misuse_child() {
    let Some((tag, lib)) = child_case() else {
        return;
    };
    let p = prefix_of(&tag);
    let ab = g(&p, "abytes");
    let max = gmax(&p);
    let k = vec![3u8; g(&p, "keybytes")];
    let npub = vec![4u8; g(&p, "npubbytes")];
    let mbuf = [0u8; 64];
    let mut cbuf = canary(128);
    let mut tagbuf = canary(64);
    let mut maclen = 0xA5A5_A5A5_A5A5_A5A5u64;
    let mut clen = 0xA5A5_A5A5_A5A5_A5A5u64;

    let parts: Vec<&str> = tag.split('/').collect();
    let (func, cond) = (parts[1], parts[2]);
    let big = match cond {
        "mlen=max+1" | "adlen=max+1" => max + 1,
        "mlen=u64max" | "adlen=u64max" => u64::MAX,
        other => panic!("unknown condition {other}"),
    };

    match func {
        "encrypt" => {
            // observe *clen_p (must remain untouched: the guard precedes it)
            set_observation((&raw const clen).cast(), 8);
            let f = sym::<Enc>(lib, &format!("{p}_encrypt"));
            let (mlen, adlen) = if cond.starts_with("mlen") { (big, 0) } else { (0, big) };
            let rc = unsafe {
                f(cbuf.as_mut_ptr(), &raw mut clen, mbuf.as_ptr(), mlen,
                  std::ptr::null(), adlen, std::ptr::null(), npub.as_ptr(), k.as_ptr())
            };
            println!("OBS returned rc={rc} clen={clen} ab={ab}");
        }
        "encrypt_detached" => {
            // observe *maclen_p, which IS written before the abort
            set_observation((&raw const maclen).cast(), 8);
            let f = sym::<EncDet>(lib, &format!("{p}_encrypt_detached"));
            let (mlen, adlen) = if cond.starts_with("mlen") { (big, 0) } else { (0, big) };
            let rc = unsafe {
                f(cbuf.as_mut_ptr(), tagbuf.as_mut_ptr(), &raw mut maclen, mbuf.as_ptr(),
                  mlen, std::ptr::null(), adlen, std::ptr::null(), npub.as_ptr(), k.as_ptr())
            };
            println!("OBS returned rc={rc} maclen={maclen}");
        }
        other => panic!("unknown function {other}"),
    }
    // If we get here, the library did NOT abort.
    use std::io::Write;
    let _ = std::io::stdout().flush();
    std::process::exit(0);
}

#[test]
fn misuse_paths_match() {
    if child_tag().is_some() {
        return;
    }
    setup();
    for &tag in MISUSE_CASES {
        let c = run_child("misuse_child", "c", tag);
        let r = run_child("misuse_child", "r", tag);
        eq_child(tag, &c, &r);
        // the C reference must genuinely have gone through sodium_misuse()
        assert_eq!(
            c.status.code(),
            Some(MISUSE_EXIT),
            "{tag}: C did not reach sodium_misuse (stdout: {}, stderr: {})",
            String::from_utf8_lossy(&c.stdout),
            String::from_utf8_lossy(&c.stderr)
        );
    }
}

/// ERRORS rows recorded as **not constructible** — documented here so the row
/// is not silently dropped, with the reason and the place the same C branch
/// *is* covered.
#[test]
fn documented_unreachable_error_rows() {
    setup();
    // 1. `crypto_aead_chacha20poly1305_encrypt_detached` / `xchacha..._encrypt_detached`
    //    have no length guard of their own; the only downstream guard is
    //    `mlen > SODIUM_SIZE_MAX (= u64::MAX)`, which an `unsigned long long`
    //    argument can never exceed. Assert the constant so the claim is checked.
    for p in ["crypto_stream_chacha20"] {
        let m = unsafe {
            sym::<unsafe extern "C" fn() -> u64>(c_lib(), &format!("{p}_messagebytes_max"))()
        };
        let m2 = unsafe {
            sym::<unsafe extern "C" fn() -> u64>(r_lib(), &format!("{p}_messagebytes_max"))()
        };
        assert_eq!(m, m2);
        assert_eq!(m, u64::MAX, "{p}_MESSAGEBYTES_MAX must be unfireable");
    }
    // 2. `crypto_aead_chacha20poly1305_ietf_{encrypt,decrypt}_detached` with
    //    `mlen > 64*(2^32-1)` aborts inside `crypto_stream_chacha20_ietf_xor_ic`
    //    (counter-overflow guard). Reaching it through the AEAD needs a 256 GiB
    //    buffer, but the *same* C branch is driven directly, out of process, by
    //    `t19_core_errors::misuse_paths_match` (tags
    //    `ietf_xor_ic/mlen=65,ic=0xffffffff` and friends), and the valid side of
    //    the same counter arithmetic by
    //    `t02_lowlevel::stream_chacha20_ietf_xor_ic_32bit_counter`.
    let ietf_max = unsafe {
        sym::<unsafe extern "C" fn() -> u64>(c_lib(), "crypto_aead_chacha20poly1305_ietf_messagebytes_max")()
    };
    assert_eq!(ietf_max, 64 * (u32::MAX as u64));
    // 3. `aegis128l_mac`/`aegis256_mac` with `maclen ∉ {16, 32}` is dead code:
    //    the wrappers hard-code `maclen = ABYTES = 32`. Verified by the
    //    constant, which is the only value the public API can produce.
    for p in ["crypto_aead_aegis128l", "crypto_aead_aegis256"] {
        assert_eq!(g(p, "abytes"), 32, "{p}_ABYTES pins aegis*_mac's maclen");
    }
    // 4. NULL `c`/`mac`/`npub`/`k` are `__attribute__((nonnull))` parameters:
    //    the C performs no runtime check, so passing NULL is UB, not a defined
    //    rejection. Not testable differentially.
}

// ===========================================================================
// ERRORS G3-078 — `sodium_misuse()` with NO handler installed
//
// `_misuse_handler` is a file-scope `static` defaulting to NULL, so unless a
// handler is installed `sodium_misuse()` falls straight through to `abort()`.
// The rest of this file installs an observing handler (which turns the abort
// into exit code 77); this pair of tests checks the *default* behaviour, i.e.
// that both libraries really die with SIGABRT.
// ===========================================================================

#[test]
fn misuse_no_handler_child() {
    let Some(tag) = child_tag() else {
        return;
    };
    if !tag.starts_with("nohandler/") {
        return;
    }
    setup(); // NOTE: deliberately does *not* install a misuse handler
    let lib = child_lib();
    let p = "crypto_aead_aegis128l";
    let max = gmax(p);
    let k = [1u8; 16];
    let npub = [2u8; 16];
    let m = [0u8; 64];
    let mut c = canary(128);
    let f = sym::<Enc>(lib, &format!("{p}_encrypt"));
    let rc = unsafe {
        f(
            c.as_mut_ptr(),
            std::ptr::null_mut(),
            m.as_ptr(),
            max + 1,
            std::ptr::null(),
            0,
            std::ptr::null(),
            npub.as_ptr(),
            k.as_ptr(),
        )
    };
    println!("OBS unexpectedly returned rc={rc}");
    use std::io::Write;
    let _ = std::io::stdout().flush();
    std::process::exit(0);
}

#[test]
fn misuse_without_handler_aborts_identically() {
    if child_tag().is_some() {
        return;
    }
    setup();
    use std::os::unix::process::ExitStatusExt;
    let tag = "nohandler/aegis128l/encrypt/mlen=max+1";
    let c = run_child("misuse_no_handler_child", "c", tag);
    let r = run_child("misuse_no_handler_child", "r", tag);
    eq_child(tag, &c, &r);
    assert_eq!(
        c.status.signal(),
        Some(6),
        "C must die with SIGABRT when no misuse handler is installed (code={:?}, stderr={})",
        c.status.code(),
        String::from_utf8_lossy(&c.stderr)
    );
    assert_eq!(r.status.signal(), Some(6), "Rust must also die with SIGABRT");
}
